const page=figma.root.children.find(p=>p.id==='49:2'); await figma.setCurrentPageAsync(page);
const screens=['01_Splash','02_Welcome','03_Create_Account_Empty','03_Create_Account_Filled','03_Create_Account_Error','04_Home','05_My_Asset_Overlay','06_Notification','07_Profile','08_Contact_Info','09_Bank_Account_Info'];
const top=page.children;
const comps=top.filter(n=>!screens.includes(n.name));
// pack
let x=0,y=1400,rowH=0;const MAXW=3200;
for(const n of comps){ if(x+n.width>MAXW){x=0;y+=rowH+60;rowH=0;} n.x=x;n.y=y;x+=n.width+60;rowH=Math.max(rowH,n.height);}
// section label
const lbl=figma.createText();await figma.loadFontAsync({family:'DM Sans',style:'Bold'});lbl.fontName={family:'DM Sans',style:'Bold'};lbl.fontSize=28;lbl.characters='Components — Paradise Invest';lbl.x=0;lbl.y=1330;page.appendChild(lbl);
const lbl2=figma.createText();lbl2.fontName={family:'DM Sans',style:'Bold'};lbl2.fontSize=28;lbl2.characters='Screens (11)';lbl2.x=0;lbl2.y=-60;page.appendChild(lbl2);
// checks
const out=[];
for(const s of screens){const f=page.children.find(n=>n.name===s);const bad=[];f.findAll(n=>n.type==='TEXT').forEach(t=>{const b=t.absoluteBoundingBox,fb=f.absoluteBoundingBox;if(b.x+b.width>fb.x+fb.width+1||b.x<fb.x-1)bad.push(t.characters.slice(0,20));});out.push(s+' '+f.width+'x'+f.height+' '+bad.join('|'));}
const ca=page.children.find(n=>n.name==='03_Create_Account_Error');
out.push(ca.findAll(n=>n.type==='TEXT').map(t=>t.characters+'@'+Math.round(t.absoluteBoundingBox.y-ca.absoluteBoundingBox.y)).join(' ; '));
const hm=page.children.find(n=>n.name==='04_Home');
out.push(hm.children.map(c=>c.name+'@'+Math.round(c.y)+'+'+Math.round(c.height)).join(' ; '));
return out.join('\n');
